	if !ok {
		t.Fatalf("expected FTHybridCmd, got %T", m.lastCmd)
	}
	assertVectorParam(t, gotCmd.args, "embedding", "__vector_param_1", blob0)
	assertVectorParam(t, gotCmd.args, "embedding2", "__vector_param_2", blob1)
}

